import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  /** Hashed password. Absent for accounts created via an OAuth provider only. */
  passwordHash?: string;
};

const users: User[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
  },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

/**
 * Creates a new email/password user. Throws if the email is already taken.
 */
export async function createUser(params: {
  email: string;
  password: string;
  name: string;
}): Promise<User> {
  const email = params.email.trim().toLowerCase();
  if (await getUserByEmail(email)) {
    throw new Error("An account with that email already exists.");
  }

  const passwordHash = await bcrypt.hash(params.password, 10);
  const user: User = {
    id: String(nextId++),
    email,
    name: params.name.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return user;
}

/**
 * Finds or creates a user for an OAuth sign-in (e.g. Google), which has no password.
 */
export async function findOrCreateOAuthUser(params: {
  email: string;
  name?: string | null;
}): Promise<User> {
  const existing = await getUserByEmail(params.email);
  if (existing) return existing;

  const email = params.email.trim().toLowerCase();
  const user: User = {
    id: String(nextId++),
    email,
    name: params.name?.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  return user;
}

/**
 * Verifies email/password credentials. Returns the user on success, or
 * undefined if the email is unknown, has no password set, or the password
 * doesn't match.
 */
export async function verifyPassword(
  email: string,
  password: string,
): Promise<User | undefined> {
  const user = await getUserByEmail(email);
  if (!user?.passwordHash) return undefined;

  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? user : undefined;
}

