import { redirect } from "next/navigation";
import { getCurrentUser, listUsers } from "@/lib/users";
import { signOutAction } from "./actions";

export default async function DashboardPage() {
  const me = await getCurrentUser();

  // The /dashboard middleware already gates unauthenticated requests; this
  // is a defense-in-depth check in case the page is ever reached another way.
  if (!me) {
    redirect("/signin?callbackUrl=/dashboard");
  }

  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <form action={signOutAction}>
          <button
            type="submit"
            className="rounded-full border border-black/[.08] px-4 py-1.5 text-sm font-medium transition-colors hover:bg-black/[.04] dark:border-white/[.145] dark:hover:bg-[#1a1a1a]"
          >
            Sign out
          </button>
        </form>
      </div>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me.name} ({me.email})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

